-- GENERAL CONSTRUCTION - Daily Construction Log
--
-- The longest of the working-document templates: site header (weather,
-- permit #, work hours), crew/subcontractor workforce table, equipment &
-- materials delivered table, an OSHA §1926 safety checklist plus a 2-photo
-- "Safety conditions / signage" row, work progress & inspections table,
-- delays & RFI log, a Snippets terms-and-conditions placeholder
-- ("[INSERT SNIPPET]"), and a sign-off table. No merge tokens -- every field
-- is hand-filled per day, matching the ADJUSTING/CLEANING/GENERAL
-- CONSTRUCTION working-document family (as opposed to the numbered
-- Pre-Built Report family's auto-personalized cover).
INSERT INTO public.document_templates (slug, team_id, created_by, name, body, fields)
VALUES (
  'example-general-construction-daily-log',
  NULL,
  NULL,
  'GENERAL CONSTRUCTION - Daily Construction Log',
  jsonb_build_object(
    'style', 'report',
    'description', 'Site header, crew/equipment logs, OSHA safety checklist, work progress, delays/RFI log, and sign-off.',
    'html', $html$<h1>GENERAL CONSTRUCTION - Daily Construction Log</h1><h2>Site Header</h2><table><tbody><tr><th><p>Field</p></th><th><p>Value</p></th></tr><tr><td><p>Project</p></td><td><p></p></td></tr><tr><td><p>GC / Superintendent</p></td><td><p></p></td></tr><tr><td><p>Date</p></td><td><p></p></td></tr><tr><td><p>Permit #</p></td><td><p></p></td></tr><tr><td><p>Weather (Temp &deg;F / RH % / Wind mph)</p></td><td><p></p></td></tr><tr><td><p>Work Hours (Start&ndash;Stop)</p></td><td><p></p></td></tr></tbody></table><hr><h2>Crew &amp; Subcontractor Workforce</h2><table><tbody><tr><th><p>Trade</p></th><th><p>Company</p></th><th><p>Crew Count</p></th><th><p>Work Performed</p></th><th><p>Hours</p></th><th><p>📷 Photo</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><h2>Equipment &amp; Materials Delivered</h2><table><tbody><tr><th><p>Time</p></th><th><p>Equipment / Material</p></th><th><p>Qty</p></th><th><p>Received By</p></th><th><p>Condition</p></th><th><p>📷 Photo</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><h2>Safety Checklist (OSHA &sect;1926)</h2><ul data-type="taskList"><li data-type="taskItem" data-checked="false"><p>Toolbox talk conducted</p></li><li data-type="taskItem" data-checked="false"><p>Fall-protection in place (&sect;1926.501)</p></li><li data-type="taskItem" data-checked="false"><p>Trenches &ge;5 ft shored (&sect;1926.652)</p></li><li data-type="taskItem" data-checked="false"><p>Housekeeping OK &ndash; no debris tripping hazards</p></li><li data-type="taskItem" data-checked="false"><p>First-aid / eyewash station stocked</p></li><li data-type="taskItem" data-checked="false"><p>Incident / Near-Miss reported (attach if Y)</p></li></ul><p>Safety conditions / signage</p><p><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F%3E%3Ctext%20x%3D'110'%20y%3D'132'%20font-family%3D'sans-serif'%20font-size%3D'14'%20font-weight%3D'700'%20fill%3D'rgb(107%2C114%2C128)'%20text-anchor%3D'middle'%3EPhoto%201%3C%2Ftext%3E%3Ctext%20x%3D'110'%20y%3D'152'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(156%2C163%2C175)'%20text-anchor%3D'middle'%3EClick%20to%20add%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="280" alt="Photo slot 1"><img src="data:image/svg+xml;utf8,%3Csvg%20xmlns%3D'http%3A%2F%2Fwww.w3.org%2F2000%2Fsvg'%20width%3D'220'%20height%3D'280'%3E%3Crect%20x%3D'0.5'%20y%3D'0.5'%20width%3D'219'%20height%3D'279'%20rx%3D'6'%20fill%3D'rgb(244%2C245%2C247)'%20stroke%3D'rgb(203%2C208%2C216)'%20stroke-dasharray%3D'5%204'%2F%3E%3Ctext%20x%3D'110'%20y%3D'132'%20font-family%3D'sans-serif'%20font-size%3D'14'%20font-weight%3D'700'%20fill%3D'rgb(107%2C114%2C128)'%20text-anchor%3D'middle'%3EPhoto%202%3C%2Ftext%3E%3Ctext%20x%3D'110'%20y%3D'152'%20font-family%3D'sans-serif'%20font-size%3D'11'%20fill%3D'rgb(156%2C163%2C175)'%20text-anchor%3D'middle'%3EClick%20to%20add%3C%2Ftext%3E%3C%2Fsvg%3E" width="32%" height="280" alt="Photo slot 2"></p><hr><h2>Work Progress &amp; Inspections</h2><table><tbody><tr><th><p>Discipline</p></th><th><p>Completed Scope</p></th><th><p>% Complete</p></th><th><p>Inspector Notes</p></th><th><p>📷 Photo</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><hr><h2>Delays &amp; RFI Log</h2><table><tbody><tr><th><p>Time</p></th><th><p>Issue</p></th><th><p>RFI #</p></th><th><p>Sent To</p></th><th><p>Response Due</p></th><th><p>Schedule Impact</p></th></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr><tr><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td><td><p></p></td></tr></tbody></table><p><strong><u>Standard Terms &amp; Conditions</u></strong> <span style="color: rgb(59,130,246)">[INSERT SNIPPET]</span></p><p><em>Log prepared per AIA G712 and IBC Chapter 1 &sect;110.</em></p><p><em>Deviations must be documented via RFI within 24 hours.</em></p><hr><h2>Sign-off</h2><table><tbody><tr><th><p>Role</p></th><th><p>Name</p></th><th><p>Date</p></th><th><p>Signature</p></th></tr><tr><td><p>Site Superintendent</p></td><td><p></p></td><td><p></p></td><td><p>✍️</p></td></tr><tr><td><p>Owner / Rep (optional)</p></td><td><p></p></td><td><p></p></td><td><p>✍️</p></td></tr></tbody></table>$html$
  ),
